entries[23077] = { ["name"] = "Gyrofrosteisreflektor", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nThoriumapparat (6), Echtsilberumwandler (2), Blauer Saphir (2), Essenz des Feuers (4), Frostöl (2), Eiskappe (4)\nGyrofrosteisreflektor\nWird beim Anlegen gebunden\nSchmuck\n+15 Frostwiderstand\n47\nBenötigt Ingenieurskunst\n(260)" }
